1	-- Policies check access once per query, not once per row: (SELECT ...) runs each user-level lookup once,
2	-- in the same form as the my_* views.
3	-- A row shared through ResourceAccess also needs partial access to its space, as in the views.
4	-- Shared rows are checked one at a time through my_resource_grants, because my_accessible_resources() can't be inlined and would build all the caller's grants for each query.
5	
6	-- Security invoker on purpose: ResourceAccess's own select policy still applies, and callers can already read their own grants.
7	-- Unlike my_accessible_resources(), the planner can inline a view, so a policy can check one row through the ResourceAccess index without building all the caller's grants.
8	CREATE OR REPLACE VIEW public.my_resource_grants WITH (security_invoker) AS
9	SELECT ra.space_id, ra.source_local_id
10	FROM public."ResourceAccess" AS ra
11	WHERE ra.account_uid = any((SELECT array_agg(my.uid) FROM public.my_user_accounts() AS my (uid))::uuid[]);
12	
13	COMMENT ON VIEW public.my_resource_grants IS 'security utility: the resources granted to me or my groups. Used by the select policies of the shared resources.';
14	
15	REVOKE ALL ON public.my_resource_grants FROM public, anon, authenticated, service_role;
16	GRANT SELECT ON public.my_resource_grants TO anon, authenticated, service_role;
