CREATE OR REPLACE FUNCTION public.file_access(hashvalue VARCHAR) RETURNS boolean
SET search_path = ''
SECURITY DEFINER
LANGUAGE sql AS $$
SELECT EXISTS (
    SELECT true FROM public."FileReference"
    WHERE filehash = hashvalue AND (
