import re,subprocess
def show(p): return subprocess.run(['git','show','a33d462ff:packages/database/supabase/'+p],capture_output=True,text=True).stdout
mig=show('migrations/20261030120000_rls_once_per_query.sql')
sch=''.join(show('schemas/'+f+'.sql') for f in 'account content embedding assets concept contributor'.split())
def norm(s): return re.sub(r'\s+','',s).lower()
def stmts(s,pat):
    out={}
    for m in re.finditer(pat,s,re.S|re.I):
        out[m.group(1)]=norm(m.group(0))
    return out
pat=r'CREATE POLICY (\w+) ON .*?;'
m,c=stmts(mig,pat),stmts(sch,pat)
print(len(m),'policies in migration')
for k,v in m.items():
    print(k,'OK' if c.get(k)==v else 'DIFF', '' if c.get(k)==v else (v,c.get(k)))
# per-row policies still in schema not in migration
for k,v in c.items():
    if k not in m: print('schema-only',k,v[:140])
for pat2 in [r'CREATE OR REPLACE VIEW public\.my_resource_grants.*?;',r'COMMENT ON POLICY (\w+).*?;',r'CREATE OR REPLACE FUNCTION public\.file_access.*?\$\$;']:
    a=[norm(x.group(0)) for x in re.finditer(pat2,mig,re.S)]
    b=[norm(x.group(0)) for x in re.finditer(pat2,sch,re.S)]
    print(pat2[:40],len(a),all(x in b for x in a))
EOF

